import 'package:dart_style/dart_style.dart';

import '../config.dart';
import '../ir.dart';
import 'strings.dart';

const _header =
    '// GENERATED CODE - DO NOT MODIFY BY HAND\n'
    '// Generated by flutter_native_widget_gen.\n\n'
    '// ignore_for_file: type=lint\n\n';

String formatDart(String source) {
  try {
    return DartFormatter(
      languageVersion: DartFormatter.latestLanguageVersion,
    ).format(source);
  } on FormatterException {
    return source;
  }
}

/// The `part` file next to a library with `@HomeScreenWidget` classes.
String emitDartPart(LibraryIR library, String partOf) {
  final out = StringBuffer(_header)..writeln("part of '$partOf';\n");
  for (final widget in library.widgets) {
    _emitWidget(out, widget);
  }
  if (library.widgets.any(
    (w) => w.fields.any((f) => f.type == FieldType.dateTime),
  )) {
    out.writeln(_dateHelper);
  }
  return formatDart(out.toString());
}

String _dartType(FieldType type) => switch (type) {
  FieldType.string || FieldType.image => 'String',
  FieldType.integer => 'int',
  FieldType.decimal => 'double',
  FieldType.boolean => 'bool',
  FieldType.dateTime => 'DateTime',
};

/// Dart expression converting [value] (of [type]) to its stored string.
String _toStored(FieldType type, String value) => switch (type) {
  FieldType.string || FieldType.image => value,
  FieldType.integer || FieldType.decimal => '$value.toString()',
  FieldType.boolean => "($value ? 'true' : 'false')",
  FieldType.dateTime => '$value.millisecondsSinceEpoch.toString()',
};

/// Dart expression parsing the stored string [raw] into [type].
String _fromStored(FieldType type, String raw) => switch (type) {
  FieldType.string || FieldType.image => raw,
  FieldType.integer => 'int.tryParse($raw)',
  FieldType.decimal => 'double.tryParse($raw)',
  FieldType.boolean => "($raw == 'true')",
  FieldType.dateTime => '_\$fnwDate($raw)',
};

const _dateHelper = r'''
DateTime? _$fnwDate(String raw) {
  final millis = int.tryParse(raw);
  return millis == null ? null : DateTime.fromMillisecondsSinceEpoch(millis);
}
''';

String _paramType(FieldIR f) =>
    f.repeat == null ? '${_dartType(f.type)}?' : 'List<${_dartType(f.type)}>?';

void _emitWidget(StringBuffer out, WidgetIR w) {
  final cls = '${w.name}Widget';
  final data = '${w.name}Data';
  final entry = '${w.name}TimelineEntry';
  final params = [for (final f in w.fields) '${_paramType(f)} ${f.key}'];

  // Map literal entries turning fields into stored strings. Parameters are
  // promoted after the null check; public fields are not and need `!`.
  String valuesMap({required bool promoted}) {
    final bang = promoted ? '' : '!';
    final b = StringBuffer();
    for (final f in w.fields) {
      final v = f.key;
      if (f.repeat == null) {
        b.writeln(
          "if ($v != null) '${f.key}': ${_toStored(f.type, '$v$bang')},",
        );
      } else {
        b.writeln('if ($v != null)');
        b.writeln('  for (var i = 0; i < ${f.repeat}; i++)');
        b.writeln(
          "    '${f.key}\$i': i < $v$bang.length ? "
          "${_toStored(f.type, '$v$bang[i]')} : null,",
        );
      }
    }
    return b.toString();
  }

  out.writeln('/// Generated API for the `${w.name}` home screen widget.');
  out.writeln('abstract final class $cls {');
  out.writeln("  static const name = ${dartString(w.name)};\n");
  out.writeln('  /// Initial value of every stored key.');
  out.writeln('  static const initialValues = <String, String>{');
  for (final MapEntry(:key, :value) in w.initialValues.entries) {
    out.writeln('    ${dartString(key)}: ${dartString(value)},');
  }
  out.writeln('  };\n');

  if (w.fields.isNotEmpty) {
    out.writeln('  /// Saves the given values (others stay as they are) and');
    out.writeln('  /// redraws the widget unless [update] is false.');
    out.writeln('  static Future<void> save({');
    for (final p in params) {
      out.writeln('    $p,');
    }
    out.writeln('    bool update = true,');
    out.writeln('  }) => FlutterNativeWidget.save(name, {');
    out.write(valuesMap(promoted: true));
    out.writeln('  }, update: update);\n');

    for (final o in w.options) {
      final option = upperFirst(o.key);
      out.writeln('  /// Choices of the `${o.key}` option.');
      out.writeln(
        '  static const ${o.key}Choices = [${o.choices.map(dartString).join(', ')}];\n',
      );
      out.writeln(
        '  /// Saves values shown only on copies of the widget whose '
        '`${o.key}` is [choice].',
      );
      out.writeln('  static Future<void> saveFor$option(String choice, {');
      for (final p in params) {
        out.writeln('    $p,');
      }
      out.writeln('    bool update = true,');
      out.writeln('  }) => FlutterNativeWidget.save(name, {');
      out.writeln(
        '    for (final MapEntry(:key, :value) in <String, String?>{',
      );
      out.write(valuesMap(promoted: true));
      out.writeln("    }.entries) '\$key@\$choice': value,");
      out.writeln('  }, update: update);\n');
    }

    out.writeln(
      '  /// Removes the given keys so their initial values show again.',
    );
    out.writeln('  static Future<void> clear({bool update = true}) =>');
    out.writeln('      FlutterNativeWidget.save(name, {');
    out.writeln('        for (final key in initialValues.keys) key: null,');
    out.writeln('      }, update: update);\n');

    out.writeln('  /// The values currently stored for the widget.');
    out.writeln('  static Future<$data> read() async {');
    out.writeln('    Future<String> raw(String key) async =>');
    out.writeln(
      '        await FlutterNativeWidget.read(name, key) ?? '
      "initialValues[key] ?? '';",
    );
    out.writeln('    return $data(');
    for (final f in w.fields) {
      if (f.repeat == null) {
        out.writeln(
          '      ${f.key}: ${_fromStored(f.type, "await raw('${f.key}')")},',
        );
      } else {
        out.writeln('      ${f.key}: [');
        out.writeln('        for (var i = 0; i < ${f.repeat}; i++)');
        out.writeln(
          "          ${_fromStored(f.type, "await raw('${f.key}\$i')")},",
        );
        out.writeln('      ],');
      }
    }
    out.writeln('    );');
    out.writeln('  }\n');

    out.writeln('  /// Values that take over at given times, shown even while');
    out.writeln(
      '  /// the app is not running. Replaces the previous timeline.',
    );
    out.writeln(
      '  static Future<void> saveTimeline(List<$entry> entries, '
      '{bool update = true}) =>',
    );
    out.writeln('      FlutterNativeWidget.saveTimeline(name, [');
    out.writeln('        for (final e in entries)');
    out.writeln('          WidgetTimelineEntry(e.startsAt, e.toValues()),');
    out.writeln('      ], update: update);\n');

    for (final f in w.fields.where((f) => f.type == FieldType.image)) {
      final method = 'render${upperFirst(f.key)}';
      out.writeln(
        '  /// Renders [child] to an image and saves it into `${f.key}`.',
      );
      if (f.repeat == null) {
        out.writeln(
          '  static Future<void> $method(Widget child, '
          '{Size size = const Size(300, 150), bool update = true}) async {',
        );
        out.writeln(
          "    final path = await FlutterNativeWidget.renderImage(child, "
          "widget: name, field: '${f.key}', logicalSize: size);",
        );
        out.writeln(
          "    await FlutterNativeWidget.save(name, {'${f.key}': path}, "
          'update: update);',
        );
      } else {
        out.writeln(
          '  static Future<void> $method(int index, Widget child, '
          '{Size size = const Size(300, 150), bool update = true}) async {',
        );
        out.writeln(
          "    final path = await FlutterNativeWidget.renderImage(child, "
          "widget: name, field: '${f.key}\$index', logicalSize: size);",
        );
        out.writeln(
          "    await FlutterNativeWidget.save(name, {'${f.key}\$index': path}, "
          'update: update);',
        );
      }
      out.writeln('  }\n');
    }
  }

  out.writeln('  /// Redraws every instance of the widget.');
  out.writeln(
    '  static Future<void> update() => FlutterNativeWidget.update(name);',
  );
  out.writeln('}\n');

  if (w.fields.isEmpty) return;

  // Data class returned by read().
  out.writeln('/// Values stored for the `${w.name}` widget.');
  out.writeln('class $data {');
  for (final f in w.fields) {
    out.writeln('  final ${_paramType(f)} ${f.key};');
  }
  out.writeln('\n  const $data({');
  for (final f in w.fields) {
    out.writeln('    this.${f.key},');
  }
  out.writeln('  });\n');
  out.writeln('  @override');
  out.writeln(
    "  String toString() => '$data(${[for (final f in w.fields) '${f.key}: \$${f.key}'].join(', ')})';",
  );
  out.writeln('}\n');

  // Timeline entry.
  out.writeln('/// One step of the `${w.name}` timeline.');
  out.writeln('class $entry {');
  out.writeln('  /// From this moment on, the values below are shown.');
  out.writeln('  final DateTime startsAt;');
  for (final f in w.fields) {
    out.writeln('  final ${_paramType(f)} ${f.key};');
  }
  out.writeln('\n  const $entry(this.startsAt, {');
  for (final f in w.fields) {
    out.writeln('    this.${f.key},');
  }
  out.writeln('  });\n');
  out.writeln('  Map<String, String?> toValues() => {');
  out.write(valuesMap(promoted: false));
  out.writeln('  };');
  out.writeln('}\n');
}

/// `lib/home_widgets.g.dart`: specs, callbacks and `initializeHomeWidgets()`.
String emitRegistry(List<LibraryIR> libraries, ProjectConfig config) {
  final out = StringBuffer(_header);
  out.writeln(
    "import 'package:flutter_native_widget/flutter_native_widget.dart';",
  );
  final callbackLibraries = [
    for (final l in libraries)
      if (l.callbacks.isNotEmpty) l.uri,
  ];
  for (final (i, uri) in callbackLibraries.indexed) {
    out.writeln("import '$uri' as i$i;");
  }
  out.writeln();
  out.writeln(
    'const homeWidgetsAppGroupId = '
    '${config.iosAppGroup == null ? 'null' : dartString(config.iosAppGroup!)};\n',
  );
  out.writeln('const homeWidgetSpecs = <WidgetSpec>[');
  for (final l in libraries) {
    for (final w in l.widgets) {
      out.writeln('  WidgetSpec(');
      out.writeln('    name: ${dartString(w.name)},');
      if (w.hasHomeScreen) {
        out.writeln(
          '    androidProvider: '
          '${dartString(config.androidProviderClass(w.name))},',
        );
      }
      out.writeln('    initialValues: {');
      for (final MapEntry(:key, :value) in w.initialValues.entries) {
        out.writeln('      ${dartString(key)}: ${dartString(value)},');
      }
      out.writeln('    },');
      out.writeln('  ),');
    }
  }
  out.writeln('];\n');

  out.writeln('final homeWidgetCallbacks = <RegisteredCallback>[');
  for (final (i, uri) in callbackLibraries.indexed) {
    final library = libraries.firstWhere((l) => l.uri == uri);
    for (final c in library.callbacks) {
      out.writeln(
        '  RegisteredCallback(${c.widget == null ? 'null' : dartString(c.widget!)}, '
        'i$i.${c.function}),',
      );
    }
  }
  out.writeln('];\n');

  out.writeln('/// Runs in a background isolate when a widget callback fires.');
  out.writeln("@pragma('vm:entry-point')");
  out.writeln('Future<void> homeWidgetsBackgroundDispatcher(Uri? uri) async {');
  out.writeln('  await FlutterNativeWidget.configure(');
  out.writeln('    iOSAppGroupId: homeWidgetsAppGroupId,');
  out.writeln('    widgets: homeWidgetSpecs,');
  out.writeln('    callbacks: homeWidgetCallbacks,');
  out.writeln('  );');
  out.writeln('  await FlutterNativeWidget.handleUri(uri);');
  out.writeln('}\n');

  out.writeln(
    '/// Call once in `main()` before using the generated widget classes.',
  );
  out.writeln('Future<void> initializeHomeWidgets() =>');
  out.writeln('    FlutterNativeWidget.initialize(');
  out.writeln('      iOSAppGroupId: homeWidgetsAppGroupId,');
  out.writeln('      widgets: homeWidgetSpecs,');
  out.writeln('      callbacks: homeWidgetCallbacks,');
  out.writeln('      backgroundDispatcher: homeWidgetsBackgroundDispatcher,');
  out.writeln('    );');
  return formatDart(out.toString());
}
